{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにあった「働きかけは、政治資金規正法、国家公務員倫理法、行政手続法（意見公募）など個別の制度で規律される。」という重要な内容がhsからすべて抜け落ちている。",
      "fix": "stdの内容に合わせて、個別制度による規律についてもhsに書き加える。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdはロビー活動のルールについての問いかけだが、hsでは「願いを国にとどける方法があるのを知っていますか？」と全く異なる内容になっており、中身が大きくずれている。",
      "fix": "stdの内容に沿って、ロビー活動が日本でどのようなルールで行われているかについての問いかけに直す。"
    },
    {
      "type": "名前と数字",
      "where": "blocks/3/text の hs",
      "detail": "stdにある「本省課長補佐級以上の職員に贈与等報告を求める（法第6条）」という具体的な役職や条文に関する情報がhsから抜けている。",
      "fix": "必要な情報をhsにも補う。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/5/text の hs",
      "detail": "stdの「出どころを確認できる公式な意見が見つからなかったため」に対し、hsでは「どの政党などが公式にどんな考えを出しているかを確認できなかったため」と「政党」という言葉を勝手に補って中身が変わっている。",
      "fix": "stdに合わせて「どの政党など」ではなく公式な意見を確認できなかった旨に修正する。"
    }
  ]
}
